+        // index map so that all key->index mappings remain consistent.
+        // Previously, the index map was only rebuilt when removing an
+        // item that was not the last in the list. That left a stale
+        // mapping for the removed key when the last item was removed,
+        // which could cause getIndex() to return a non-negative index
+        // for a key that no longer exists. Subsequent setValue() calls
+        // would then attempt to update a position outside the current
+        // list bounds, triggering IndexOutOfBoundsException.
+        this.keys.remove(index);
+        this.values.remove(index);
+        // Always rebuild to remove the deleted key and fix subsequent indices.
+        rebuildIndex();
     }
