+          // Determine if this is a constant var by checking the first
+          // reference to it. Don't check the declaration, as it might be null.
+          //
+          // The ref node can be one of:
+          // - GETPROP (for assignments like a.b = ...), where the property
+          //   name is the last child of the GETPROP node.
+          // - STRING (for object literal keys), where the STRING node itself
+          //   represents the property name.
+          // Guard against other node types and missing children to avoid NPEs.
+          if (p.refs != null && !p.refs.isEmpty()) {
+            Node refNode = p.refs.get(0).node;
+            Node propNameNode = null;
+            if (refNode != null) {
+              switch (refNode.getType()) {
+                case Token.GETPROP:
+                  propNameNode = refNode.getLastChild();
+                  break;
+                case Token.STRING:
+                  propNameNode = refNode;
+                  break;
+                default:
+                  // Other node types (e.g., NAME) do not carry a property
+                  // name token we can inspect for constness here.
+                  break;
+              }
+            }
+            if (propNameNode != null &&
+                propNameNode.getBooleanProp(Node.IS_CONSTANT_NAME)) {
+              nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
+            }
+          }
         }
       }
     }
     return numStubs;
   }
 }
