+
+  // Scans the function body for return/throw statements.
+  // Returns an array of three booleans:
+  // [0] hasAnyReturn, [1] hasReturnWithValue, [2] hasThrow
+  private boolean[] scanForReturnsAndThrows(Node n) {
+    boolean hasAnyReturn = false;
+    boolean hasReturnWithValue = false;
+    boolean hasThrow = false;
+    for (Node child = n.getFirstChild(); child != null; child = child.getNext()) {
+      int type = child.getType();
+      if (type == Token.FUNCTION) {
+        // Do not consider returns inside nested functions.
+        continue;
+      }
+      if (type == Token.RETURN) {
+        hasAnyReturn = true;
+        if (child.getFirstChild() != null) {
+          hasReturnWithValue = true;
+        }
+      } else if (type == Token.THROW) {
+        hasThrow = true;
+      }
+      // Recurse into children to find nested returns/throws (excluding nested functions).
+      boolean[] sub = scanForReturnsAndThrows(child);
+      hasAnyReturn = hasAnyReturn || sub[0];
+      hasReturnWithValue = hasReturnWithValue || sub[1];
+      hasThrow = hasThrow || sub[2];
+    }
+    return new boolean[] {hasAnyReturn, hasReturnWithValue, hasThrow};
+  }
