+    /**
+     * Ensure the internal buffer exists and has enough space for the next write.
+     *
+     * Historically, this method only doubled the existing buffer when more
+     * capacity was needed. However, when the buffer was initially set via
+     * {@link #setInitialBuffer(byte[], int, int)} to point at a very small
+     * external array (e.g., a single-byte array used by InputStream.read()),
+     * a single doubling may still leave the buffer too small for the minimum
+     * write size (which is {@code encodeSize}, i.e., at least 4 bytes).
+     *
+     * To avoid ArrayIndexOutOfBoundsException in such cases (see CODEC-105),
+     * we now grow the buffer to at least {@code pos + encodeSize} bytes.
+     */
+    private void resizeBuffer() {
+        if (buffer == null) {
+            buffer = new byte[DEFAULT_BUFFER_SIZE];
+            pos = 0;
+            readPos = 0;
+        } else {
+            int minCapacity = pos + encodeSize;
+            int newLen = buffer.length * DEFAULT_BUFFER_RESIZE_FACTOR;
+            if (newLen < minCapacity) {
+                newLen = minCapacity;
+            }
+            byte[] b = new byte[newLen];
+            System.arraycopy(buffer, 0, b, 0, buffer.length);
+            buffer = b;
+        }
+    }
*** End Patch
