+
+            @Override
+            public CSVRecord next() {
+                if (CSVParser.this.isClosed()) {
+                    throw new NoSuchElementException("CSVParser has been closed");
+                }
+                CSVRecord next = CSVParser.this.nextRecordCache;
+                CSVParser.this.nextRecordCache = null;
+
+                if (next == null) {
+                    // hasNext() wasn't called before; fetch now
+                    next = this.getNextRecord();
