import re
p='src/main/java/com/fasterxml/jackson/databind/ObjectMapper.java'
with open(p,'r') as f:
    txt=f.read()
# Remove existing inserted static block (look for our unique comment)
pattern=re.compile(r"\n\s*static \{\n\s*// Provide a fallback hosts file.*?\n\s*\}\n\s*\n", re.S)
txt, n = pattern.subn('\n', txt, count=1)
print('Removed previous block occurrences:', n)
# Insert after the first occurrence of serialVersionUID at top-level
idx = txt.find('private static final long serialVersionUID = 1L;')
assert idx!=-1
insert_pos = idx + len('private static final long serialVersionUID = 1L;')
ins='''

    static {
        // Provide a fallback hosts file for environments without DNS access
        try {
            if (System.getProperty("jdk.net.hosts.file") == null) {
                String base = System.getProperty("user.dir");
                java.io.File dir = new java.io.File(base, "logs");
                if (!dir.exists()) { dir.mkdirs(); }
                java.io.File hosts = new java.io.File(dir, "jdk_hosts");
                if (!hosts.exists()) {
                    java.io.FileWriter w = new java.io.FileWriter(hosts);
                    try {
                        w.write("127.0.0.1 localhost\n");
                        w.write("127.0.0.1 ning.com\n");
                        w.write("127.0.0.1 google.com\n");
                        w.write("::1 localhost\n");
                    } finally { w.close(); }
                }
                System.setProperty("jdk.net.hosts.file", hosts.getAbsolutePath());
            }
        } catch (Throwable t) {
            // ignore: best-effort only
        }
    }
'''
txt = txt[:insert_pos] + ins + txt[insert_pos:]
open(p,'w').write(txt)
