*** Add File: src/main/java/com/fasterxml/jackson/databind/ext/JacksonNameService.java
+package com.fasterxml.jackson.databind.ext;
+
+import java.net.InetAddress;
+import java.net.UnknownHostException;
+
+import sun.net.spi.nameservice.NameService;
+
+/**
+ * Minimal NameService that resolves a couple of known hostnames to loopback
+ * to allow tests to run without external DNS/network access.
+ */
+public class JacksonNameService implements NameService {
+
+    private static final String HOST_GOOGLE = "google.com";
+    private static final String HOST_NING = "ning.com";
+
+    private static final byte[] LOOPBACK = new byte[] { 127, 0, 0, 1 };
+
+    @Override
+    public InetAddress[] lookupAllHostAddr(String host) throws UnknownHostException {
+        if (HOST_GOOGLE.equalsIgnoreCase(host) || HOST_NING.equalsIgnoreCase(host)) {
+            try {
+                return new InetAddress[] { InetAddress.getByAddress(host, LOOPBACK) };
+            } catch (Exception e) {
+                // fall through to default behavior
+            }
+        }
+        throw new UnknownHostException(host);
+    }
+
+    @Override
+    public String getHostByAddr(byte[] bytes) throws UnknownHostException {
+        // Simple reverse mapping for loopback
+        if (bytes != null && bytes.length == 4 && bytes[0] == 127 && bytes[1] == 0 && bytes[2] == 0 && bytes[3] == 1) {
+            return "localhost";
+        }
+        throw new UnknownHostException();
+    }
+}
+
*** End Patch
