import java.net.*;import java.lang.reflect.*;import java.util.*;public class CreateInetCacheEntry{public static void main(String[]a)throws Exception{String host="ning.com";InetAddress ia=InetAddress.getByAddress(host,new byte[]{127,0,0,1});Field cf=InetAddress.class.getDeclaredField("cache");cf.setAccessible(true);Map m=(Map)cf.get(null);
Class<?> cachedCls=null;for(Object e:m.entrySet()){Object val=((Map.Entry)e).getValue();cachedCls=val.getClass();break;}System.out.println("Cached class="+cachedCls);
// Try to find a constructor that takes (InetAddress[] addrs, long expiry)
Constructor<?> cons=null;for(Constructor<?> c:cachedCls.getDeclaredConstructors()){System.out.println(c);cons=c;}
// Fallback: try to set fields via reflection
Object cached;
try{cons.setAccessible(true);cached=cons.newInstance(new Object[]{new InetAddress[]{ia}});}catch(Throwable t){cached=cachedCls.newInstance();}
System.out.println("Created: "+cached);
// Try to put into map
m.put(host,cached);
System.out.println("Map put done; lookup: "+InetAddress.getByName(host));
}
}
