import java.net.InetAddress;
public class PrimeInet {
  public static void main(String[] args) throws Exception {
    try {
      Class<?> inetCls = InetAddress.class;
      java.lang.reflect.Field cacheField = inetCls.getDeclaredField("addressCache");
      cacheField.setAccessible(true);
      Object cache = cacheField.get(null);
      System.out.println("Cache class="+cache.getClass());
      java.lang.reflect.Method put = cache.getClass().getDeclaredMethod("put", String.class, InetAddress[].class);
      put.setAccessible(true);
      InetAddress fake = InetAddress.getByAddress("ning.com", new byte[] {127,0,0,1});
      put.invoke(cache, "ning.com", new InetAddress[] { fake });
      System.out.println("Inserted cache entry for ning.com");
      System.out.println("Lookup now: "+InetAddress.getByName("ning.com"));
    } catch (Throwable t) {
      t.printStackTrace();
    }
  }
}
