     public VisibilityChecker<?> getDefaultVisibilityChecker()
     {
         VisibilityChecker<?> vchecker = super.getDefaultVisibilityChecker();
+        // Ensure that serialization-side introspection respects global auto-detect
+        // settings consistently with deserialization (see [databind#48]).
+        // In particular, when AUTO_DETECT_SETTERS is disabled, setters should
+        // not contribute implicit properties during serialization introspection.
+        if (!isEnabled(MapperFeature.AUTO_DETECT_SETTERS)) {
+            vchecker = vchecker.withSetterVisibility(Visibility.NONE);
+        }
         // then global overrides (disabling)
         if (!isEnabled(MapperFeature.AUTO_DETECT_GETTERS)) {
             vchecker = vchecker.withGetterVisibility(Visibility.NONE);
         }
         if (!isEnabled(MapperFeature.AUTO_DETECT_IS_GETTERS)) {
             vchecker = vchecker.withIsGetterVisibility(Visibility.NONE);
         }
         if (!isEnabled(MapperFeature.AUTO_DETECT_FIELDS)) {
             vchecker = vchecker.withFieldVisibility(Visibility.NONE);
         }
         return vchecker;
     }
