+                    return InetAddress.getByName(value);
+                } catch (java.net.UnknownHostException e) {
+                    // In restricted or offline environments, name lookup may fail.
+                    // Create an unresolved address with the given hostname so that
+                    // callers can still access the host name without requiring DNS.
+                    // Use an IPv6 zero address if the input looks like IPv6, otherwise IPv4.
