+    private void combinator(char combinator) {
+        tq.consumeWhitespace();
+        // Consume the next sub-query up to the next top-level combinator.
+        // Must respect balanced [...] and (...) so that combinator-like chars inside
+        // attribute selectors (e.g., ~=) or pseudos are not misinterpreted.
+        StringBuilder sq = new StringBuilder();
+        while (!tq.isEmpty()) {
+            if (tq.matches("[")) {
+                sq.append('[').append(tq.chompBalanced('[', ']')).append(']');
+                continue;
+            }
+            if (tq.matches("(")) {
+                sq.append('(').append(tq.chompBalanced('(', ')')).append(')');
+                continue;
+            }
+            if (tq.matchesAny(combinators)) {
+                break; // reached next combinator at top level
+            }
+            sq.append(tq.consume());
+        }
+        String subQuery = sq.toString();
