+    // merge multiple <head> or <body> contents into one, delete the remainder, and ensure they are owned by <html>
+    private void normaliseStructure(Element htmlEl) {
+        // Head
+        List<Element> heads = getElementsByTag("head");
+        Element headEl = heads.isEmpty() ? null : heads.get(0);
+        if (headEl == null) {
+            headEl = htmlEl.prependElement("head");
+        } else {
+            if (headEl.parent() != htmlEl) {
+                headEl.remove();
+                htmlEl.prependChild(headEl);
+            }
+            for (int i = 1; i < heads.size(); i++) {
+                Element dup = heads.get(i);
+                // move children into the head
+                int childSize = dup.childNodes.size();
+                for (int j = 0; j < childSize; j++) {
+                    Node child = dup.childNodes.get(0);
+                    dup.removeChild(child);
+                    headEl.appendChild(child);
+                }
+                dup.remove();
+            }
+        }
+
+        // Body
+        List<Element> bodies = getElementsByTag("body");
+        Element bodyEl = bodies.isEmpty() ? null : bodies.get(0);
+        if (bodyEl == null) {
+            bodyEl = htmlEl.appendElement("body");
+        } else {
+            if (bodyEl.parent() != htmlEl) {
+                bodyEl.remove();
+                htmlEl.appendChild(bodyEl);
+            }
+            for (int i = 1; i < bodies.size(); i++) {
+                Element dup = bodies.get(i);
+                // append children of subsequent bodies to the first body, then remove duplicate
+                int childSize = dup.childNodes.size();
+                for (int j = 0; j < childSize; j++) {
+                    Node child = dup.childNodes.get(0);
+                    dup.removeChild(child);
+                    bodyEl.appendChild(child);
+                }
+                dup.remove();
+            }
+        }
+    }
