import java.util.*;
import org.apache.commons.lang.text.ExtendedMessageFormat;
public class QuickMain {
  public static void main(String[] args) {
    String pattern = "1: {0,date,short}";
    Date d = new GregorianCalendar(2007, Calendar.JANUARY, 23).getTime();
    MessageFormat mf = new MessageFormat(pattern);
    ExtendedMessageFormat emf = new ExtendedMessageFormat(pattern);
    System.out.println("Default locale: " + Locale.getDefault());
    System.out.println("MF locale: " + mf.getLocale());
    System.out.println("EMF locale: " + emf.getLocale());
    System.out.println("MF:  " + mf.format(new Object[]{d}));
    System.out.println("EMF: " + emf.format(new Object[]{d}));
  }
}
