+        final int len = str.length();
+        if (len < 2) {
+            throw new IllegalArgumentException("Invalid locale format: " + str);
+        }
+        // Handle the special case where the string starts with an underscore,
+        // meaning the language is missing, but the country (and optionally variant) is present.
+        if (str.charAt(0) == '_') {
+            if (len < 3) {
+                throw new IllegalArgumentException("Invalid locale format: " + str);
+            }
+            final char ch1 = str.charAt(1);
+            final char ch2 = str.charAt(2);
+            if (!Character.isUpperCase(ch1) || !Character.isUpperCase(ch2)) {
+                throw new IllegalArgumentException("Invalid locale format: " + str);
+            }
+            if (len == 3) {
+                // e.g. _GB -> new Locale("", "GB")
+                return new Locale("", str.substring(1, 3));
+            }
+            if (len < 5) {
+                // must have at least "_GB_" + variant => 5 chars
+                throw new IllegalArgumentException("Invalid locale format: " + str);
+            }
+            if (str.charAt(3) != '_') {
+                throw new IllegalArgumentException("Invalid locale format: " + str);
+            }
+            return new Locale("", str.substring(1, 3), str.substring(4));
+        }
+
+        final char ch0 = str.charAt(0);
+        final char ch1 = str.charAt(1);
+        if (!Character.isLowerCase(ch0) || !Character.isLowerCase(ch1)) {
+            throw new IllegalArgumentException("Invalid locale format: " + str);
+        }
+        if (len == 2) {
+            return new Locale(str);
+        }
+        if (len < 5) {
+            throw new IllegalArgumentException("Invalid locale format: " + str);
+        }
+        if (str.charAt(2) != '_') {
+            throw new IllegalArgumentException("Invalid locale format: " + str);
+        }
+        final char ch3 = str.charAt(3);
+        if (ch3 == '_') {
+            // language + variant, no country
+            return new Locale(str.substring(0, 2), "", str.substring(4));
+        }
+        final char ch4 = str.charAt(4);
+        if (!Character.isUpperCase(ch3) || !Character.isUpperCase(ch4)) {
+            throw new IllegalArgumentException("Invalid locale format: " + str);
+        }
+        if (len == 5) {
+            return new Locale(str.substring(0, 2), str.substring(3, 5));
