import java.text.*;
import java.util.*;
public class TimeCheck {
  public static void main(String[] args) {
    Locale def = Locale.getDefault();
    TimeZone tz = TimeZone.getTimeZone("America/Los_Angeles");
    TimeZone.setDefault(tz);
    Date d1 = new GregorianCalendar(1970, Calendar.JANUARY, 1, 0, 15, 20).getTime();
    DateFormat dfDefLong = DateFormat.getTimeInstance(DateFormat.LONG);
    DateFormat dfDefFull = DateFormat.getTimeInstance(DateFormat.FULL);
    System.out.println("Default locale="+def+", LONG="+dfDefLong.format(d1));
    System.out.println("Default locale="+def+", FULL="+dfDefFull.format(d1));

    Locale us = Locale.US;
    DateFormat dfUSLong = DateFormat.getTimeInstance(DateFormat.LONG, us);
    DateFormat dfUSFull = DateFormat.getTimeInstance(DateFormat.FULL, us);
    System.out.println("US LONG="+dfUSLong.format(d1));
    System.out.println("US FULL="+dfUSFull.format(d1));

    MessageFormat mfLong = new MessageFormat("Time: {0,time,long}", us);
    MessageFormat mfFull = new MessageFormat("Time: {0,time,full}", us);
    System.out.println(mfLong.format(new Object[]{d1}));
    System.out.println(mfFull.format(new Object[]{d1}));
  }
}
EOF
