import java.text.*; 
import java.util.*; 
import org.apache.commons.lang.time.DateUtils;

public class SimulateLang59 {
  static void check(String label, Date exp, Date act, DateFormat fmt){
    boolean ok = exp.equals(act);
    System.out.println(label+": "+(ok?"OK":"FAIL")+" exp="+fmt.format(exp)+" ("+exp.getTime()+") act="+fmt.format(act)+" ("+act.getTime()+")");
  }
  public static void main(String[] args) throws Exception {
    TimeZone defaultZone = TimeZone.getDefault();
    // Mountain Time
    TimeZone MST_MDT = TimeZone.getTimeZone("MST7MDT");
    TimeZone.setDefault(MST_MDT);
    DateFormat format = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS z");
    format.setTimeZone(MST_MDT);

    Date oct31_01MDT = new Date(1099206000000L); 

    Date oct31MDT             = new Date(oct31_01MDT.getTime()       - 3600000L); // - 1 hour
    Date oct31_01_02MDT       = new Date(oct31_01MDT.getTime()       + 120000L);  // + 2 minutes
    Date oct31_01_02_03MDT    = new Date(oct31_01_02MDT.getTime()    + 3000L);    // + 3 seconds
    Date oct31_01_02_03_04MDT = new Date(oct31_01_02_03MDT.getTime() + 4L);       // + 4 milliseconds

    check("Truncate MILLISECOND",
          oct31_01_02_03_04MDT, DateUtils.truncate(oct31_01_02_03_04MDT, Calendar.MILLISECOND), format);
    check("Truncate SECOND   ",
          oct31_01_02_03MDT, DateUtils.truncate(oct31_01_02_03_04MDT, Calendar.SECOND), format);
    check("Truncate MINUTE   ",
          oct31_01_02MDT, DateUtils.truncate(oct31_01_02_03_04MDT, Calendar.MINUTE), format);
    check("Truncate HOUR_OF_DAY",
          oct31_01MDT, DateUtils.truncate(oct31_01_02_03_04MDT, Calendar.HOUR_OF_DAY), format);
    check("Truncate HOUR",
          oct31_01MDT, DateUtils.truncate(oct31_01_02_03_04MDT, Calendar.HOUR), format);
    check("Truncate DATE",
          oct31MDT, DateUtils.truncate(oct31_01_02_03_04MDT, Calendar.DATE), format);

    TimeZone.setDefault(defaultZone);
  }
}
