ant compile -q && mkdir -p tools && cat > tools/Runner.java << 'EOF'
import org.apache.commons.math3.optimization.direct.CMAESOptimizer;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.analysis.MultivariateFunction;

public class Runner {
  public static void main(String[] args) {
    final CMAESOptimizer optimizer = new CMAESOptimizer();
    final MultivariateFunction fitnessFunction = new MultivariateFunction() {
      public double value(double[] parameters) {
        final double target = 11.1;
        final double error = target - parameters[0];
        return error * error;
      }
    };
    final double[] start = { 1 };

    PointValuePair result = optimizer.optimize(100000, fitnessFunction, GoalType.MINIMIZE, start);
    final double resNoBound = result.getPoint()[0];

    final double[] lower = { -20 };
    final double[] upper = { 5e16 };
    result = optimizer.optimize(100000, fitnessFunction, GoalType.MINIMIZE, start, lower, upper);
    final double resNearLo = result.getPoint()[0];

    lower[0] = -5e16;
    upper[0] = 20;
    result = optimizer.optimize(100000, fitnessFunction, GoalType.MINIMIZE, start, lower, upper);
    final double resNearHi = result.getPoint()[0];

    System.out.println("resNoBound=" + resNoBound);
    System.out.println("resNearLo=" + resNearLo);
    System.out.println("resNearHi=" + resNearHi);
  }
}
EOF

javac -cp target/classes -d tools tools/Runner.java && java -cp target/classes:tools Runner

