+    public RectangularCholeskyDecomposition(RealMatrix matrix, double small)
+        throws NonPositiveDefiniteMatrixException {
+
+        final int order = matrix.getRowDimension();
+
+        // Identify active (non-zero variance) indices using the diagonal.
+        // For a symmetric positive semidefinite matrix, any exact zero
+        // diagonal implies a corresponding zero row/column.
+        int[] active = new int[order];
+        int r = 0;
+        for (int i = 0; i < order; ++i) {
+            if (matrix.getEntry(i, i) >= small) {
+                active[r++] = i;
+            }
+        }
+
+        if (r == 0) {
+            // All diagonal entries are smaller than threshold -> not PSD
+            throw new NonPositiveDefiniteMatrixException(0.0, 0, small);
+        }
+
+        // Build the active submatrix and perform standard Cholesky on it.
+        int[] rows = new int[r];
+        System.arraycopy(active, 0, rows, 0, r);
+        RealMatrix sub = matrix.getSubMatrix(rows, rows);
+
+        // Use a conservative relative symmetry threshold and the provided
+        // absolute positivity threshold to align with callers' expectations.
+        final CholeskyDecomposition chol = new CholeskyDecomposition(sub, 1.0e-15, small);
+        final RealMatrix l = chol.getL();
+
+        // Expand back to full-size rectangular root: place the factor rows
+        // at the corresponding original indices; leave zero rows elsewhere.
+        rank = r;
+        root = MatrixUtils.createRealMatrix(order, r);
+        for (int i = 0; i < r; ++i) {
+            for (int j = 0; j < r; ++j) {
+                root.setEntry(rows[i], j, l.getEntry(i, j));
+            }
+        }
+    }
