import org.apache.commons.math3.linear.*;

public class TestRunner2 {
  static void run(double[][] md, double small) {
    RealMatrix m = MatrixUtils.createRealMatrix(md);
    RectangularCholeskyDecomposition d = new RectangularCholeskyDecomposition(m, small);
    RealMatrix root = d.getRootMatrix();
    RealMatrix rebuilt = root.multiply(root.transpose());
    RealMatrix diff = m.subtract(rebuilt);
    System.out.println("rank="+d.getRank()+", norm="+diff.getNorm());
    for (int i=0; i<Math.min(4, m.getRowDimension()); ++i) {
      for (int j=0; j<Math.min(4, m.getColumnDimension()); ++j) {
        double v = diff.getEntry(i,j);
        System.out.print(String.format("% .12f ", v));
      }
      System.out.println();
    }
  }
  public static void main(String[] args) {
    double[][] m1d = new double[][]{
      {0.013445532, 0.010394690, 0.009881156, 0.010499559},
      {0.010394690, 0.023006616, 0.008196856, 0.010732709},
      {0.009881156, 0.008196856, 0.019023866, 0.009210099},
      {0.010499559, 0.010732709, 0.009210099, 0.019107243}
    };
    run(m1d, 1e-10);

    double[][] base = new double[][]{
      { 0.1159548705,      0.,           0.,           0.      },
      { 0.0896442724, 0.1223540781,      0.,           0.      },
      { 0.0852155322, 0.004558668,  0.1083577299,      0.      },
      { 0.0905486674, 0.0213768077, 0.0128878333, 0.1014155693 }
    };
    RealMatrix B = MatrixUtils.createRealMatrix(base);
    double[][] md = B.multiply(B.transpose()).getData();
    run(md, 1e-10);
  }
}
