+        // Reproduce residual minimization check from testMath320A
+        double[] b = new double[] {5.0, 6.0, 7.0};
+        double[] x = svdFull.getSolver().solve(b);
+        double[] ax = rm1.operate(x);
+        double res = 0;
+        for (int i = 0; i < ax.length; ++i) {
+            double d = ax[i] - b[i];
+            res += d * d;
+        }
+        res = Math.sqrt(res);
+        double epsilon = 2 * Math.ulp(res);
+        double h = 0.1;
+        int k = 3;
+        boolean ok = true;
+        double worst = Double.NEGATIVE_INFINITY;
+        for (double d0 = -k * h; d0 <= k * h; d0 += h) {
+            for (double d1 = -k * h ; d1 <= k * h; d1 += h) {
+                for (double d2 = -k * h; d2 <= k * h; d2 += h) {
+                    double[] xx = new double[] { x[0] + d0, x[1] + d1, x[2] + d2 };
+                    double[] axt = rm1.operate(xx);
+                    double sum = 0;
+                    for (int ii = 0; ii < axt.length; ++ii) {
+                        double dd = axt[ii] - b[ii];
+                        sum += dd * dd;
+                    }
+                    double rr = Math.sqrt(sum);
+                    worst = Math.max(worst, res - rr);
+                    if ((rr - res) < -epsilon) {
+                        ok = false;
+                    }
+                }
+            }
+        }
+        System.out.println("Residual: " + res + ", ok: " + ok + ", worst margin: " + worst + ", eps: " + epsilon);
