jshell << 'EOF'
/cp target/classes
import org.apache.commons.math.linear.*;
var a = new Array2DRowRealMatrix(new double[][]{{1,2,3},{2,3,4},{3,5,7}});
var bidi = new BiDiagonalTransformer(a);
var main = bidi.getMainDiagonalRef();
var sec = bidi.getSecondaryDiagonalRef();
var mainTri = new double[main.length];
var secTri = new double[main.length-1];
var x = main[0];
mainTri[0]=x*x;
for(int i=1;i<main.length;++i){
  double b=sec[i-1];
  secTri[i-1]=x*b; x=main[i]; mainTri[i]=x*x + b*b;
}
var ed = new EigenDecompositionImpl(mainTri, secTri, org.apache.commons.math.util.MathUtils.SAFE_MIN);
System.out.println(java.util.Arrays.toString(ed.getRealEigenvalues()));
/exit
EOF

