     public RealPointValuePair doOptimize()
         throws OptimizationException {
         final SimplexTableau tableau =
             new SimplexTableau(f, constraints, goalType, restrictToNonNegative, epsilon);
         solvePhase1(tableau);
         tableau.discardArtificialVariables();
+        // After removing artificial variables, ensure Phase 2 objective is in
+        // canonical form with respect to the current basis. This zeros out
+        // coefficients in the objective row for all basic variables so that
+        // the solver can properly continue optimizing the original objective.
+        for (int i = tableau.getNumObjectiveFunctions(); i < tableau.getWidth() - 1; i++) {
+            Integer basicRow = tableau.getBasicRow(i);
+            if (basicRow != null) {
+                double coeff = tableau.getEntry(0, i);
+                if (MathUtils.compareTo(coeff, 0.0, epsilon) != 0) {
+                    tableau.subtractRow(0, basicRow, coeff);
+                }
+            }
+        }
         while (!isOptimal(tableau)) {
             doIteration(tableau);
         }
         return tableau.getSolution();
     }
