+        // If multiple decision variable columns correspond to the same basic row
+        // (e.g. an equality like x1 + x2 = b), prefer the variable whose reduced
+        // cost (objective row coefficient) is closest to zero (i.e. likely basic).
+        int[] varBasicRow = new int[n];
+        for (int i = 0; i < n; i++) {
+            Integer br = getBasicRow(getNumObjectiveFunctions() + i);
+            varBasicRow[i] = (br == null) ? -1 : br.intValue();
+        }
+        // Map each basic row to the selected decision variable index
+        int height = getHeight();
+        int[] selectedVarForRow = new int[height];
+        for (int r = 0; r < height; r++) {
+            selectedVarForRow[r] = -1;
+        }
+        for (int i = 0; i < n; i++) {
+            int br = varBasicRow[i];
+            if (br >= 0) {
+                int col = getNumObjectiveFunctions() + i;
+                double rc = Math.abs(getEntry(0, col));
+                int prevVar = selectedVarForRow[br];
+                if (prevVar < 0) {
+                    selectedVarForRow[br] = i;
+                } else {
+                    int prevCol = getNumObjectiveFunctions() + prevVar;
+                    double prevRc = Math.abs(getEntry(0, prevCol));
+                    if (rc < prevRc - epsilon) {
+                        selectedVarForRow[br] = i;
+                    }
+                }
+            }
+        }
+
+        // Assign values based on the selected mapping
+        for (int i = 0; i < n; i++) {
+            int br = varBasicRow[i];
+            if (br >= 0 && selectedVarForRow[br] == i) {
+                coefficients[i] = getEntry(br, getRhsOffset()) - (restrictToNonNegative ? 0 : mostNegative);
+            } else {
+                coefficients[i] = 0.0;
+            }
+        }
+
+        return new RealPointValuePair(coefficients, f.getValue(coefficients));
+    }
