-            date.getYear() + 1900,
-            date.getMonth() + 1,
-            date.getDate()
-        );
+        // Determine era from a Calendar to correctly handle BC years,
+        // then convert to proleptic ISO year where 1 BC == year 0
+        int yearOfEra = date.getYear() + 1900;
+        GregorianCalendar cal = new GregorianCalendar();
+        cal.setTime(date);
+        int era = cal.get(Calendar.ERA);
+        int prolepticYear = (era == GregorianCalendar.AD ? yearOfEra : 1 - yearOfEra);
+        return new LocalDate(
+            prolepticYear,
+            date.getMonth() + 1,
+            date.getDate()
+        );
     }
