import java.util.*;
public class CheckBC{
  public static void main(String[]args){
    GregorianCalendar cal = new GregorianCalendar(1, Calendar.FEBRUARY, 3, 4, 5, 6);
    cal.set(Calendar.ERA, GregorianCalendar.BC);
    cal.set(Calendar.MILLISECOND, 7);
    Date d = cal.getTime();
    System.out.println("cal era="+cal.get(Calendar.ERA)+" year="+cal.get(Calendar.YEAR));
    System.out.println("date y=" + (d.getYear()+1900)+" m="+(d.getMonth()+1)+" d="+d.getDate());
    System.out.println("millis="+d.getTime());
    GregorianCalendar cal2 = new GregorianCalendar(); cal2.setTime(d);
    System.out.println("cal2 era="+cal2.get(Calendar.ERA)+" y="+cal2.get(Calendar.YEAR));
  }
}
EOF
