+        public long set(long instant, int value) {
+            long localInstant = iZone.convertUTCToLocal(instant);
+            localInstant = iField.set(localInstant, value);
+
+            // For time fields (hours/minutes/seconds/millis), prefer retaining
+            // the original offset during overlaps where the local instant is
+            // ambiguous. This matches expectations to "retain offset" when
+            // only sub-day fields change across DST fall-back transitions.
+            if (iTimeField) {
+                int offset = getOffsetToAdd(instant);
+                long tentative = localInstant - offset;
+                // Check overflow the same way as in duration add logic
+                if (((localInstant ^ tentative) < 0) && ((localInstant ^ (-offset)) < 0)) {
+                    // overflow: fall through to default conversion
+                } else {
+                    // If using the original offset yields a valid mapping, use it.
+                    if (iZone.getOffset(tentative) == offset) {
+                        if (get(tentative) == value) {
+                            return tentative;
+                        }
+                    }
+                }
+            }
+
+            long result = iZone.convertLocalToUTC(localInstant, false);
+            if (get(result) != value) {
+                throw new IllegalFieldValueException(iField.getType(), new Integer(value),
+                    "Illegal instant due to time zone offset transition: " +
+                    DateTimeFormat.forPattern("yyyy-MM-dd'T'HH:mm:ss.SSS").print(new Instant(localInstant)) +
+                    " (" + iZone.getID() + ")");
+            }
+            return result;
+        }
